/* ============================== HOOKS & HELPERS ========================= */
function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const fn = (e) => setReduced(e.matches);
    mq.addEventListener ? mq.addEventListener("change", fn) : mq.addListener(fn);
    return () => (mq.removeEventListener ? mq.removeEventListener("change", fn) : mq.removeListener(fn));
  }, []);
  return reduced;
}

function Reveal({ children, className = "", delay = 0, y = 22 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  const reduced = useReducedMotion();

  useEffect(() => {
    if (reduced) { setVisible(true); return; }
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            setVisible(true);
            obs.unobserve(e.target);
          }
        });
      },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [reduced]);

  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0px) scale(1)" : `translateY(${y}px) scale(0.985)`,
        transition: `opacity 0.7s cubic-bezier(0.16,1,0.3,1) ${delay}ms, transform 0.7s cubic-bezier(0.16,1,0.3,1) ${delay}ms`,
        willChange: visible ? "auto" : "opacity, transform",
      }}
    >
      {children}
    </div>
  );
}

/* Glass card — the core surface of the whole design system */
function Glass({ t, children, hover = false, glow = false, style = {}, className = "", as: Tag = "div", ...rest }) {
  return (
    <Tag
      className={`gc ${hover ? "gc-hover" : ""} ${className}`}
      style={{
        background: t.glass,
        border: `1px solid ${t.border}`,
        borderRadius: 20,
        backdropFilter: "blur(16px)",
        WebkitBackdropFilter: "blur(16px)",
        position: "relative",
        overflow: "hidden",
        "--accent-c": t.accent,
        boxShadow: glow ? `0 0 0 1px ${t.border}, 0 20px 60px -20px rgba(0,0,0,0.55)` : `0 12px 40px -18px rgba(0,0,0,0.5)`,
        ...style,
      }}
      {...rest}
    >
      {hover && <span className="gc-sheen" aria-hidden="true" />}
      {children}
    </Tag>
  );
}

function Eyebrow({ sheet, label, t }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
      <span style={{
        fontFamily: "'IBM Plex Mono', monospace", fontSize: 11.5, letterSpacing: 2, color: t.accent,
        border: `1px solid ${t.accent}44`, padding: "3px 9px", borderRadius: 20, background: `${t.accent}0F`,
      }}>
        {sheet}
      </span>
      <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, letterSpacing: 3, color: t.textFaint }}>
        {label}
      </span>
    </div>
  );
}

function TickBar({ level, max, color, reduced }) {
  return (
    <div style={{ display: "flex", gap: 3 }}>
      {Array.from({ length: max }).map((_, i) => (
        <div
          key={i}
          style={{
            width: 14, height: 4, borderRadius: 2,
            background: i < level ? color : "rgba(255,255,255,0.12)",
            boxShadow: i < level ? `0 0 8px ${color}66` : "none",
            position: "relative", overflow: "hidden",
          }}
        >
          {i === level - 1 && !reduced && (
            <div style={{
              position: "absolute", top: 0, bottom: 0, width: "45%",
              background: "rgba(255,255,255,0.65)",
              animation: "shimmerSweep 2.6s ease-in-out 3",
            }} />
          )}
        </div>
      ))}
    </div>
  );
}

